"""Fast symmetric eigensolver using single-precision divide-and-conquer LAPACK."""
import numpy as np
from scipy.linalg.lapack import ssyevd
from numba import njit


@njit(cache=True)
def _clean_vectors(q):
    """Normalize and remove tiny leakage into nearby eigenvectors.

    Divide-and-conquer's single precision orthogonality error is concentrated
    around nearby eigenvalues.  A short-window modified Gram-Schmidt cleanup in
    double precision provides ample accuracy without the cost of a full QR.
    """
    n = q.shape[1]
    window = 16
    for j in range(n):
        lo = j - window
        if lo < 0:
            lo = 0
        for k in range(lo, j):
            dot = 0.0
            for i in range(n):
                dot += q[i, k] * q[i, j]
            for i in range(n):
                q[i, j] -= dot * q[i, k]
        norm2 = 0.0
        for i in range(n):
            norm2 += q[i, j] * q[i, j]
        scale = 1.0 / np.sqrt(norm2)
        for i in range(n):
            q[i, j] *= scale
    return q


class Solver:
    def solve(self, problem, **kwargs):
        a = np.array(problem, dtype=np.float32, order="F")
        # Extra workspace noticeably improves Accelerate's divide-and-conquer
        # implementation. The array is allowed to be destroyed by LAPACK.
        values, vectors, info = ssyevd(a, compute_v=1, lower=1,
                                       lwork=10_000_000, overwrite_a=1)
        vectors = _clean_vectors(vectors.astype(np.float64))
        rows = np.ascontiguousarray(vectors[:, ::-1].T)
        return values[::-1].tolist(), rows.tolist()
PY
