from scipy.linalg.lapack import sgeev

class Solver:
    def solve(self, problem, **kwargs):
        a=np.array(problem,dtype=np.float32,order='F')
        wr,wi,vl,vr,info=sgeev(a,compute_vl=0,compute_vr=1,overwrite_a=1)
        av=problem@vr
        out=[];j=0;n=len(wr)
        while j<n:
