import numpy as np
from scipy.linalg.lapack import sgeev
class Solver:
 def solve(self,A,**kwargs):
  a=np.array(A,dtype=np.float32,order='F')
  wr,wi,vl,vr,info=sgeev(a,compute_vl=0,compute_vr=1,overwrite_a=1)
  n=len(wr); X=np.empty((n,n),complex);j=0
  while j<n:
   if wi[j]==0:X[:,j]=vr[:,j];j+=1
   else:
    X[:,j]=vr[:,j]+1j*vr[:,j+1];X[:,j+1]=X[:,j].conj();j+=2
  Y=np.linalg.inv(X)
  AX=A@X
  z=np.einsum('ij,ji->i',Y,AX)
  return sorted(z,key=lambda x:(-x.real,-x.imag))
