"""Fast, vectorized kernel density evaluation."""
import numpy as np
from scipy.spatial.distance import cdist
from scipy.special import logsumexp
from sklearn.neighbors._ball_tree import kernel_norm


class Solver:
    def solve(self, problem, **kwargs):
        X = np.asarray(problem["data_points"], dtype=np.float64)
        Q = np.asarray(problem["query_points"], dtype=np.float64)
        if Q.shape[0] == 0:
            return {"log_density": []}
        h = float(problem["bandwidth"])
        ker = problem["kernel"]
        # Computing the full rectangular distance matrix uses scipy's tight C
        # loop and is substantially quicker than exact tree traversal for the
        # moderate, usually high-dimensional instances in this task.
        d2 = cdist(Q, X, metric="sqeuclidean")
        d2 *= 1.0 / (h * h)
        if ker == "gaussian":
            ls = logsumexp(-0.5 * d2, axis=1)
        elif ker == "exponential":
            np.sqrt(d2, out=d2)
            ls = logsumexp(-d2, axis=1)
        else:
            inside = d2 <= 1.0
            if ker == "tophat":
                sums = np.count_nonzero(inside, axis=1).astype(float)
            elif ker == "epanechnikov":
                np.subtract(1.0, d2, out=d2)
                d2[~inside] = 0.0
                sums = d2.sum(axis=1)
            elif ker == "linear":
                np.sqrt(d2, out=d2)
                np.subtract(1.0, d2, out=d2)
                d2[~inside] = 0.0
                sums = d2.sum(axis=1)
            elif ker == "cosine":
                np.sqrt(d2, out=d2)
                np.cos((np.pi / 2.0) * d2, out=d2)
                d2[~inside] = 0.0
                sums = d2.sum(axis=1)
            else:
                return {"error": "unknown kernel"}
            with np.errstate(divide="ignore"):
                ls = np.log(sums)
        ls += kernel_norm(h, X.shape[1], ker, True) - np.log(X.shape[0])
        return {"log_density": ls.tolist()}
