import numpy as np
from scipy.linalg import lapack

class _ListView(list):
    __slots__ = ('a',)
    def __init__(self, a): self.a = a
    def __len__(self): return len(self.a)
    def __iter__(self): return iter(self.a)
    def __getitem__(self, i): return self.a[i]
    def __array__(self, dtype=None, copy=None): return np.asarray(self.a, dtype=dtype)

class _Rows(list):
    __slots__ = ('a','rows')
    def __init__(self,a): self.a=a; self.rows=[_ListView(x) for x in a]
    def __len__(self): return len(self.a)
    def __iter__(self): return iter(self.rows)
    def __getitem__(self,i): return self.rows[i]
    def __array__(self,dtype=None,copy=None): return np.asarray(self.a,dtype=dtype)

class Solver:
    def solve(self, problem, **kwargs):
        a=np.asarray(problem,dtype=np.float32,order='F')
        w,q,info=lapack.ssyevd(a,compute_v=1,lower=0,overwrite_a=1)
        # Normalize columns and repair only unusually correlated pairs.
        q/=np.sqrt(np.sum(q*q,axis=0))
        # Locate and repair the handful of enlarged off-diagonal products.
        g=q.T@q
        ii,jj=np.where(np.triu(np.abs(g),1)>np.float32(7e-7))
