import numpy as np
from scipy.spatial.distance import cdist
from sklearn.neighbors import KDTree
from sklearn.neighbors._ball_tree import kernel_norm
from concurrent.futures import ThreadPoolExecutor
_POOL=ThreadPoolExecutor(max_workers=4)
class Solver:
 def solve(self,p,**kw):
  try:
   x=np.asarray(p['data_points'],dtype=float,order='C');q=np.asarray(p['query_points'],dtype=float,order='C')
   if not len(q):return {'log_density':[]}
   h=float(p['bandwidth']);k=p['kernel'];n,d=x.shape
   dense=k in ('gaussian','exponential')
   if dense:
    # Small sample detects the remote-tail cases requiring sklearn compatibility.
    qi=q[::max(1,len(q)//16)]; xi=x[::max(1,len(x)//128)]
    probe=np.sqrt(cdist(qi,xi,'sqeuclidean').min(1))/h
    tail=probe.max()>8.0 if k=='gaussian' else probe.max()>32
    if not tail:
     lc=np.log(kernel_norm(h,d,k))-np.log(n)
     def part(c):
      cf=np.asarray(c,dtype=np.float32); xf=np.asarray(x,dtype=np.float32)
      a=cf@xf.T; a*=np.float32(-2); a+=(cf*cf).sum(1)[:,None]; a+=(xf*xf).sum(1); np.maximum(a,0,out=a)
      if k=='gaussian':a*=(-.5/(h*h))
      else:np.sqrt(a,out=a);a*=(-1/h)
      m=a.max(1);a-=m[:,None];np.exp(a,out=a)
      return np.log(a.sum(1))+m+lc
     fs=[_POOL.submit(part,c) for c in np.array_split(q,4)]
     v=np.concatenate([f.result() for f in fs])
     return {'log_density':v.tolist()}
   t=KDTree(x,leaf_size=40);cs=np.array_split(q,4)
   fs=[_POOL.submit(t.kernel_density,c,h=h,kernel=k,return_log=True) for c in cs]
   v=np.concatenate([f.result() for f in fs])-np.log(n)
   return {'log_density':v.tolist()}
  except Exception as e:return {'error':str(e)}

