        """Internal helper to generate data based on distribution type."""

        if dist_params is None:
            dist_params = {}

        if distribution_type == "normal":
            mean = dist_params.get("mean", np.zeros(dims))
            cov_base = dist_params.get("cov", np.eye(dims))
