            if cov_base.shape != (dims, dims):
                cov_base = np.eye(dims)
            # Add small jitter for numerical stability if cov is identity
            cov = (
                cov_base + np.eye(dims) * 1e-6 if np.allclose(cov_base, np.eye(dims)) else cov_base
