import numpy as np
from scipy.special import logsumexp
from sklearn.neighbors._ball_tree import kernel_norm


class Solver:
    """KDE evaluated in batches using dense BLAS distance calculations."""
    def solve(self, problem, **kwargs):
        try:
            x = np.asarray(problem["data_points"], dtype=np.float64)
            q = np.asarray(problem["query_points"], dtype=np.float64)
            if x.ndim != 2 or q.ndim != 2 or not len(x) or x.shape[1] != q.shape[1]:
                raise ValueError("invalid point arrays")
            if not len(q):
                return {"log_density": []}
            h = float(problem["bandwidth"])
            ker = problem["kernel"]
            n, d = x.shape
            # ||q-x||^2, formed by a matrix product.  This is substantially
            # quicker than a tree traversal in the moderately/high dimensional
            # instances used by this task.
            d2 = q @ x.T
            d2 *= -2.0
            d2 += np.einsum('ij,ij->i', q, q)[:, None]
            d2 += np.einsum('ij,ij->i', x, x)[None, :]
            np.maximum(d2, 0.0, out=d2)

            logc = np.log(kernel_norm(h, d, ker)) - np.log(n)
            if ker == "gaussian":
                vals = logsumexp(d2 * (-0.5 / (h * h)), axis=1) + logc
            elif ker == "exponential":
                np.sqrt(d2, out=d2)
                vals = logsumexp(d2 * (-1.0 / h), axis=1) + logc
            else:
                # Reuse the distance allocation for kernel weights.
                d2 *= 1.0 / (h * h)
                inside = d2 < 1.0
                if ker == "tophat":
                    sums = np.count_nonzero(inside, axis=1).astype(float)
                elif ker == "epanechnikov":
                    np.subtract(1.0, d2, out=d2, where=inside)
                    d2[~inside] = 0.0
                    sums = d2.sum(axis=1)
                else:
                    np.sqrt(d2, out=d2)
                    if ker == "linear":
                        np.subtract(1.0, d2, out=d2, where=inside)
                    elif ker == "cosine":
                        d2 *= np.pi / 2.0
                        np.cos(d2, out=d2, where=inside)
                    else:
                        raise ValueError("unknown kernel")
                    d2[~inside] = 0.0
                    sums = d2.sum(axis=1)
                with np.errstate(divide='ignore'):
                    vals = np.log(sums) + logc
            return {"log_density": vals.tolist()}
        except Exception as e:
            return {"error": f"Computation error: {e}"}
