from scipy.special import logsumexp
from scipy.spatial.distance import cdist
from sklearn.neighbors._ball_tree import kernel_norm
from sklearn.neighbors import KDTree
from concurrent.futures import ThreadPoolExecutor

_POOL = ThreadPoolExecutor(max_workers=4)

class Solver:
    def solve(self, problem, **kwargs):
        try:
            x=np.asarray(problem['data_points'],dtype=float); q=np.asarray(problem['query_points'],dtype=float)
            if not len(q): return {'log_density':[]}
            h=float(problem['bandwidth']); ker=problem['kernel']; n,d=x.shape
            # Tree kernels release the GIL. sklearn evaluates queries serially;
            # splitting them gives identical results while using available cores.
            tree_mode = ker not in ('gaussian','exponential')
            d2 = None
            if ker in ('gaussian','exponential'):
                d2=cdist(q, x, 'sqeuclidean')
                tree_mode = np.max(np.min(d2,axis=1))/(h*h)>55 if ker == 'gaussian' else np.max(np.sqrt(np.min(d2,axis=1))/h)>30
            if tree_mode:
                tree=KDTree(x,leaf_size=40)
                chunks=np.array_split(q,4)
                fs=[_POOL.submit(tree.kernel_density,c,h=h,kernel=ker,return_log=True) for c in chunks]
                vals=np.concatenate([f.result() for f in fs])-np.log(n)
                return {'log_density':vals.tolist()}
            np.maximum(d2,0,out=d2)
            logc=np.log(kernel_norm(h,d,ker))-np.log(n)

            if ker == 'gaussian':
                d2 *= -.5/(h*h)
            else:
                np.sqrt(d2,out=d2); d2 *= -1/h
            mx=d2.max(axis=1)
            d2 -= mx[:,None]
            np.exp(d2,out=d2)
            vals=np.log(d2.sum(axis=1))+mx+logc
            return {'log_density':vals.tolist()}
        except Exception as e: return {'error':f'Computation error: {e}'}

